import os,json,re,uuid,hashlib,base64,time
from datetime import datetime,timezone
import boto3
from botocore.exceptions import ClientError
table=boto3.resource('dynamodb').Table(os.environ['TABLE_NAME'])
origin=os.environ['ALLOWED_ORIGIN']
def reply(code,data):
    return {'statusCode':code,'headers':{'Content-Type':'application/json','Cache-Control':'no-store'},'body':json.dumps(data)}
def handler(event,context):
    headers=event.get('headers') or {}
    if headers.get('origin')!=origin:
        return reply(403,{'error':'Please register using the campaign page.'})
    raw=event.get('body') or ''
    if event.get('isBase64Encoded'):
        try: raw=base64.b64decode(raw).decode('utf-8')
        except (ValueError,UnicodeError): return reply(400,{'error':'Invalid request.'})
    if len(raw)>4096: return reply(413,{'error':'Request too large.'})
    try: body=json.loads(raw)
    except (ValueError,TypeError): return reply(400,{'error':'Invalid request.'})
    if not isinstance(body,dict): return reply(400,{'error':'Invalid request.'})
    name=body.get('name');email=body.get('email');phone=body.get('phone','');amount=body.get('amount')
    if not isinstance(name,str) or not isinstance(email,str) or not isinstance(phone,str):
        return reply(400,{'error':'Please enter valid contact details.'})
    name=name.strip();email=email.strip().lower();phone=phone.strip()
    if body.get('website'): return reply(400,{'error':'Unable to register.'})
    if not 2<=len(name)<=120 or not re.fullmatch(r'[^\s@]+@[^\s@]+\.[^\s@]+',email) or len(email)>180 or len(phone)>45 or type(amount) is not int or amount not in [500,750,1000] or body.get('consent') is not True:
        return reply(400,{'error':'Please enter valid details, select a contribution and agree to be contacted.'})
    try: uuid.UUID(body.get('requestId',''))
    except (ValueError,TypeError,AttributeError): return reply(400,{'error':'Please reload the page and try again.'})
    key=hashlib.sha256(('shajara-ten-partners:'+email).encode()).hexdigest()
    item={'id':key,'name':name,'email':email,'phone':phone,'amount':amount,'consent':True,'consentVersion':'2026-10-13','created_at':datetime.now(timezone.utc).isoformat(),'expires_at':int(time.time())+365*86400,'campaign':'shajara-ten-partners'}
    try:
        table.put_item(Item=item,ConditionExpression='attribute_not_exists(id)')
    except table.meta.client.exceptions.ConditionalCheckFailedException:
        return reply(200,{'ok':True,'message':'Your interest has already been registered.'})
    except ClientError:
        return reply(503,{'error':'Registration is temporarily unavailable. Please try again later.'})
    return reply(200,{'ok':True})
